/* Allen voice: speech typing into the message box, and replies read aloud.
 *
 * Generated by om/allen-voice/voice.om; never hand-edit. Element ids, limits
 * and every visible sentence come from the vcfg table in voice.om.
 *
 * Speech typing. The microphone is touched only after a tap on the mic
 * button: nothing here asks for it, or for any permission, when the page
 * loads. Recognized words go into the message box as editable text, with an
 * input event, and are never sent: the visitor presses Send. The privacy note
 * says where the audio goes before the first tap. It says on device only when
 * the browser reports an installed on-device recognizer for the language and
 * processLocally is set; otherwise it says the browser's online speech
 * service hears the audio (Chrome sends it to Google).
 *
 * Replies read aloud. Off unless the visitor turns it on; the choice (on or
 * off, nothing else) is the only thing kept, in local storage. Uses the
 * browser's speech synthesis, never a recording of anyone. Allen's replies are
 * read as they are; a message Drake typed himself is read after the words
 * "Drake wrote:" so a synthetic voice is never taken for either of them.
 * Speech stops on a new request, a mic tap, turning it off, or when the page
 * is hidden. No transcript and no audio is stored or sent by this file.
 */
(() => {
  'use strict';
  const byId = id => document.getElementById(id);
  const input = byId('allen-input');
  const mic = byId('allen-mic');
  const privacy = byId('allen-voice-privacy');
  const toggle = byId('allen-speak');
  if (!input || (!mic && !toggle)) return;
  const STORE = 'allen-voice-speak';
  const SPEAK_MAX = 4000;
  const CHUNK = 200;
  const COPY = Object.freeze({
    cloud: "Voice typing uses your browser's online speech service: in Chrome your audio goes to Google's servers to become text, and other browsers may send it to their maker. My site never receives your audio, only the words you choose to send.",
    local: "Voice typing runs on this device: your browser turns speech into text here and your audio does not leave it. Only the words you choose to send reach Allen.",
    none: "Voice typing isn't available in this browser. You can still type your message.",
    insecure: "Voice typing needs the secure https page. You can still type your message.",
    start: "Start voice typing",
    stop: "Stop voice typing",
    starting: "Starting. Your browser may ask to use the microphone.",
    listening: "Listening. Speak, then tap the microphone again to stop, or press Escape to cancel.",
    done: "Done. Your words are in the message box: check them, then press Send.",
    nothing: "No words came through. Tap the microphone to try again.",
    cancelled: "Cancelled. The message box is back as it was.",
    blocked: "The microphone is blocked for this site. Allow it in your browser's site settings, or type instead.",
    nomic: "No microphone was found. You can type instead.",
    network: "Your browser's speech service could not be reached. Check your connection, or type instead.",
    lang: "Voice typing doesn't support this page's language in your browser.",
    failed: "Voice typing stopped with an error. You can type instead.",
    fallback: "On-device voice typing isn't ready in this browser, so it would use the online speech service. Read the privacy note, then tap the microphone again if that's fine.",
    hidden: "Voice typing stopped because the page went to the background.",
    typed: "Voice typing stopped because you started typing.",
    noSpeak: "Reading replies aloud isn't available in this browser.",
    speakOn: "Allen's replies will be read aloud by your browser's voice.",
    speakOff: "Replies are no longer read aloud.",
    remote: "Your browser lists no on-device voice for this language, so it may send reply text to its online voice service.",
    drake: "Drake wrote:",
    code: "(code block skipped)",
    link: "link",
    rest: "The rest is on the screen.",
  });

  function lang() {
    const page = document.documentElement && document.documentElement.lang;
    const nav = window.navigator && window.navigator.language;
    return String(page || nav || 'en-US');
  }

  /* One live region for both halves; made here when the page has none. */
  let status = byId('allen-voice-status');
  if (!status) {
    status = document.createElement('p');
    status.id = 'allen-voice-status';
    status.className = 'allen-voice-status';
    const after = privacy || mic || toggle;
    if (after.parentNode) after.parentNode.insertBefore(status, after.nextSibling);
  }
  status.setAttribute('role', 'status');
  status.setAttribute('aria-live', 'polite');
  function say(text) {
    if (status.textContent !== text) status.textContent = text;
  }

  /* Speech typing. */
  const Recognition = typeof window.SpeechRecognition === 'function' ? window.SpeechRecognition
    : typeof window.webkitSpeechRecognition === 'function' ? window.webkitSpeechRecognition : null;
  const secure = window.isSecureContext === true;
  const canLocal = !!Recognition && Recognition === window.SpeechRecognition
    && typeof Recognition.available === 'function' && 'processLocally' in Recognition.prototype;
  let mode = !Recognition ? 'none' : !secure ? 'insecure' : 'cloud';
  let rec = null;
  let state = 'idle';
  let base = '';
  let wrote = null;
  let writing = false;
  let heard = false;
  let ending = '';

  function showPrivacy() {
    if (privacy) privacy.textContent = COPY[mode];
    if (!mic) return;
    const off = mode === 'none' || mode === 'insecure';
    mic.disabled = off;
    mic.setAttribute('aria-disabled', off ? 'true' : 'false');
    mic.dataset.voice = mode;
    const described = [privacy && privacy.id, status.id].filter(Boolean).join(' ');
    if (described) mic.setAttribute('aria-describedby', described);
  }
  function setState(next, message) {
    state = next;
    if (mic) {
      const live = next !== 'idle';
      mic.dataset.state = next;
      mic.setAttribute('aria-pressed', live ? 'true' : 'false');
      mic.setAttribute('aria-label', live ? COPY.stop : COPY.start);
      mic.title = live ? COPY.stop : COPY.start;
    }
    if (message !== undefined) say(message);
  }

  /* Only an installed on-device recognizer counts as on device. */
  async function probe() {
    if (!canLocal || mode !== 'cloud') return;
    let answer = '';
    try {
      answer = await Recognition.available({ langs: [lang()], processLocally: true });
    } catch (_) {
      answer = '';
    }
    if (answer === 'available' && mode === 'cloud') {
      mode = 'local';
      showPrivacy();
    }
  }

  function joined(text) {
    const said = String(text).replace(/\s+/g, ' ').trim();
    if (!said) return base;
    const gap = base && !/\s$/.test(base) ? ' ' : '';
    let value = base + gap + said;
    const max = input.maxLength;
    if (max > 0 && value.length > max) value = value.slice(0, max);
    return value;
  }
  function write(value) {
    if (input.value === value) return;
    writing = true;
    input.value = value;
    wrote = value;
    try {
      input.setSelectionRange(value.length, value.length);
    } catch (_) {
      /* Some input types have no selection. */
    }
    input.dispatchEvent(new Event('input', { bubbles: true }));
    writing = false;
  }

  const ERRORS = Object.freeze({
    'not-allowed': 'blocked',
    'service-not-allowed': 'blocked',
    'audio-capture': 'nomic',
    network: 'network',
    'language-not-supported': 'lang',
    'no-speech': 'nothing',
  });

  function start() {
    if (!Recognition || (mode !== 'cloud' && mode !== 'local') || rec) return;
    stopSpeaking();
    const r = new Recognition();
    r.lang = lang();
    r.continuous = false;
    r.interimResults = true;
    r.maxAlternatives = 1;
    if (mode === 'local') r.processLocally = true;
    base = input.value;
    wrote = null;
    heard = false;
    ending = '';
    r.onaudiostart = () => {
      if (rec === r && state === 'starting') setState('listening', COPY.listening);
    };
    r.onstart = r.onaudiostart;
    r.onresult = event => {
      if (rec !== r || ending) return;
      let text = '';
      for (let i = 0; i < event.results.length; i += 1) {
        const best = event.results[i] && event.results[i][0];
        if (best && typeof best.transcript === 'string') text += best.transcript;
      }
      if (text.trim()) heard = true;
      write(joined(text));
    };
    r.onerror = event => {
      if (rec !== r) return;
      const code = event && typeof event.error === 'string' ? event.error : '';
      if (code === 'aborted') return;
      if (mode === 'local' && (code === 'language-not-supported' || code === 'service-not-allowed')) {
        mode = 'cloud';
        showPrivacy();
        ending = ending || 'fallback';
        return;
      }
      ending = ending || ERRORS[code] || 'failed';
    };
    r.onend = () => {
      if (rec !== r) return;
      rec = null;
      if (ending === 'cancelled') write(base);
      const said = ending ? COPY[ending] : heard ? COPY.done : COPY.nothing;
      setState('idle', said);
    };
    rec = r;
    setState('starting', COPY.starting);
    try {
      r.start();
    } catch (_) {
      rec = null;
      setState('idle', COPY.failed);
    }
  }
  function stop() {
    if (!rec) return;
    if (state === 'stopping') {
      rec.abort();
      return;
    }
    setState('stopping');
    rec.stop();
  }
  function end(why) {
    if (!rec) return;
    ending = why;
    setState('stopping');
    rec.abort();
  }

  if (mic) {
    showPrivacy();
    setState('idle');
    if (mode === 'none' || mode === 'insecure') say(COPY[mode]);
    mic.addEventListener('click', event => {
      event.preventDefault();
      if (state === 'idle') start();
      else stop();
    });
    input.addEventListener('input', () => {
      if (!writing && rec && input.value !== wrote) end('typed');
    });
    document.addEventListener('keydown', event => {
      if (event.key !== 'Escape' || !rec) return;
      event.preventDefault();
      event.stopPropagation();
      end('cancelled');
    }, true);
    probe();
  }

  /* Replies read aloud. */
  const synth = window.speechSynthesis && typeof window.SpeechSynthesisUtterance === 'function' ? window.speechSynthesis : null;
  const box = !!toggle && toggle.tagName === 'INPUT' && String(toggle.type).toLowerCase() === 'checkbox';
  let speaking = false;
  let unlocked = false;

  function stored() {
    try {
      return window.localStorage.getItem(STORE) === 'on';
    } catch (_) {
      return false;
    }
  }
  function store(on) {
    try {
      if (on) window.localStorage.setItem(STORE, 'on');
      else window.localStorage.removeItem(STORE);
    } catch (_) {
      /* The choice lasts for this page only. */
    }
  }
  function showToggle() {
    if (!toggle) return;
    if (box) toggle.checked = speaking;
    else toggle.setAttribute('aria-pressed', speaking ? 'true' : 'false');
    toggle.dataset.state = speaking ? 'on' : 'off';
  }
  function stopSpeaking() {
    if (synth) synth.cancel();
  }
  function voice() {
    const want = lang().toLowerCase().replace(/_/g, '-');
    const family = want.split('-')[0];
    let list = [];
    try {
      list = Array.from(synth.getVoices() || []);
    } catch (_) {
      list = [];
    }
    const tag = v => String(v && v.lang || '').toLowerCase().replace(/_/g, '-');
    const near = list.filter(v => v && v.localService === true && tag(v).split('-')[0] === family);
    return near.find(v => tag(v) === want) || near[0] || null;
  }
  /* Code is skipped, links are named, markdown marks are dropped. */
  function plain(text) {
    return String(text)
      .replace(/```[\s\S]*?(```|$)/g, ` ${COPY.code} `)
      .replace(/https?:\/\/\S+/g, COPY.link)
      .replace(/[`*_#>\x7e]+/g, '')
      .replace(/\|/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }
  function pieces(text) {
    const out = [];
    let line = '';
    for (const part of text.match(/[^.!?]+[.!?]*\s*|[.!?]+\s*/g) || []) {
      let rest = part;
      while (rest.length > CHUNK) {
        if (line) out.push(line.trim());
        line = '';
        out.push(rest.slice(0, CHUNK).trim());
        rest = rest.slice(CHUNK);
      }
      if (line.length + rest.length > CHUNK) {
        out.push(line.trim());
        line = '';
      }
      line += rest;
    }
    if (line.trim()) out.push(line.trim());
    return out.filter(Boolean);
  }
  function read(text, lead) {
    if (!speaking || !synth || document.hidden) return;
    let said = plain(text);
    if (!said) return;
    if (said.length > SPEAK_MAX) said = `${said.slice(0, SPEAK_MAX)} ${COPY.rest}`;
    stopSpeaking();
    const chosen = voice();
    for (const part of pieces(lead ? `${lead} ${said}` : said)) {
      const utterance = new window.SpeechSynthesisUtterance(part);
      utterance.lang = lang();
      if (chosen) utterance.voice = chosen;
      synth.speak(utterance);
    }
  }
  /* iOS speaks later only after one utterance inside a tap. */
  function unlock() {
    if (unlocked || !speaking || !synth) return;
    unlocked = true;
    const utterance = new window.SpeechSynthesisUtterance('');
    utterance.volume = 0;
    synth.speak(utterance);
  }
  function setSpeaking(on) {
    speaking = !!on && !!synth;
    store(speaking);
    showToggle();
    if (!speaking) {
      stopSpeaking();
      say(COPY.speakOff);
      return;
    }
    unlock();
    say(voice() ? COPY.speakOn : `${COPY.speakOn} ${COPY.remote}`);
  }

  if (toggle) {
    if (!synth) {
      toggle.disabled = true;
      toggle.setAttribute('aria-disabled', 'true');
      toggle.title = COPY.noSpeak;
      speaking = false;
    } else {
      speaking = stored();
    }
    showToggle();
    toggle.addEventListener(box ? 'change' : 'click', () => {
      if (!synth) return;
      setSpeaking(box ? toggle.checked : !speaking);
    });
  }

  function hidden() {
    if (!document.hidden) return;
    stopSpeaking();
    end('hidden');
  }
  document.addEventListener('visibilitychange', hidden);
  window.addEventListener('pagehide', () => {
    stopSpeaking();
    end('hidden');
  });

  /* The chat transport (window.allen v1): a new request silences speech;
     replies are read only when the visitor turned reading on. */
  let hooked = false;
  function hook() {
    const allen = window.allen;
    if (hooked || !allen || typeof allen.on !== 'function') return;
    hooked = true;
    allen.on('send', () => {
      stopSpeaking();
      unlock();
    });
    allen.on('reply', detail => {
      if (!detail || typeof detail.text !== 'string') return;
      if (detail.outcome === 'Stopped.') return;
      read(detail.text, '');
    });
    allen.on('human', detail => {
      if (detail && typeof detail.text === 'string') read(detail.text, COPY.drake);
    });
  }
  hook();
  document.addEventListener('allen-ready', hook);

  window.AllenVoice = Object.freeze({
    version: 1,
    mode: () => mode,
    state: () => state,
    speaking: () => speaking,
  });
})();
